{
  "families": [
    {
      "family": "pipelined",
      "ranges": [
        {"param": "data_width", "low": 12, "high": 18, "choices": null},
        {"param": "n_iter", "low": 8, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 2, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 2, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 0.8,
      "why": "Primary family: 1 result/cycle, so throughput = Fmax. It has the shortest critical path (one micro-rotation per stage) and therefore the highest Fmax of any family. Only pipelined can plausibly reach 400 MSPS on Artix-7. Ranges bracket the minimum data_width and n_iter needed for max_abs_err <= 2^-12 while minimising LUTs: W=12-18 (W>=13 likely required with rounding), N=8-20 for convergence, and small angle_guard/frac_guard/rounding options to trade accuracy for area."
    },
    {
      "family": "pipelined_m",
      "ranges": [
        {"param": "data_width", "low": 12, "high": 18, "choices": null},
        {"param": "n_iter", "low": 8, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 2, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 2, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "m", "low": 2, "high": 4, "choices": null}
      ],
      "budget_share": 0.2,
      "why": "Secondary check: also 1 result/cycle, but longer combinational path (m micro-rotations per cycle) so Fmax is expected to be lower than pipelined. Included with a small budget to verify it cannot beat pipelined on Fmax or LUTs, and to catch any routing-dominated corner where fewer pipeline registers might help. m is limited to 2-4 because larger m further lengthens the critical path and is even less likely to meet 400 MSPS."
    }
  ],
  "rationale": "The spec requires >=400 MSPS single-lane. Only pipelined and pipelined_m produce 1 result/cycle. Iterative and unrolled_k produce one result every N+3 or ceil(N/k)+3 cycles; even with the smallest N and largest k they would need Fmax > 1.6 GHz, far beyond Artix-7. Therefore they are excluded from the first round. Pipelined is the primary candidate because it has the shortest critical path and thus the highest Fmax. Pipelined_m is given a small share to confirm it is dominated for this throughput target. The parameter ranges focus on the feasible accuracy/area boundary: data_width 12-18 to find the minimum width meeting 2^-12 (W>=13 likely needed), n_iter 8-20 for convergence, and small angle_guard/frac_guard/rounding options to minimise LUTs while satisfying max_abs_err <= 0.000244141."
}
